CREATE TABLE shifts(id uuid PRIMARY KEY, branch_id uuid NOT NULL REFERENCES branches, cashier_id uuid NOT NULL REFERENCES users, opening_paisa bigint NOT NULL CHECK(opening_paisa>=0), opened_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE shift_closings(id uuid PRIMARY KEY, shift_id uuid NOT NULL UNIQUE REFERENCES shifts, expected_paisa bigint NOT NULL, counted_paisa bigint NOT NULL CHECK(counted_paisa>=0), variance_paisa bigint NOT NULL, reason text NOT NULL, actor_id uuid NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customers(id uuid PRIMARY KEY, branch_id uuid NOT NULL REFERENCES branches, name text NOT NULL, phone text NOT NULL DEFAULT '', credit_limit_paisa bigint NOT NULL DEFAULT 0 CHECK(credit_limit_paisa>=0), active boolean NOT NULL DEFAULT true);
ALTER TABLE sales ADD COLUMN shift_id uuid REFERENCES shifts;
ALTER TABLE sales ADD COLUMN customer_id uuid REFERENCES customers;
ALTER TABLE sales ADD COLUMN credit_paisa bigint NOT NULL DEFAULT 0 CHECK(credit_paisa>=0);
CREATE INDEX sales_shift ON sales(shift_id);
CREATE TABLE returns(id uuid PRIMARY KEY, branch_id uuid NOT NULL REFERENCES branches, sale_id uuid NOT NULL REFERENCES sales, idempotency_key uuid NOT NULL, request_hash text NOT NULL, amount_paisa bigint NOT NULL CHECK(amount_paisa>=0), tax_paisa bigint NOT NULL DEFAULT 0 CHECK(tax_paisa>=0), refund_paisa bigint NOT NULL CHECK(refund_paisa>=0), credit_reduction_paisa bigint NOT NULL CHECK(credit_reduction_paisa>=0), method text NOT NULL CHECK(method IN ('CASH','CARD','WALLET')), reason text NOT NULL, actor_id uuid NOT NULL REFERENCES users, shift_id uuid REFERENCES shifts, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(branch_id,idempotency_key));
CREATE TABLE return_lines(id uuid PRIMARY KEY, return_id uuid NOT NULL REFERENCES returns, line_id uuid NOT NULL REFERENCES sale_lines, quantity integer NOT NULL CHECK(quantity>0), amount_paisa bigint NOT NULL CHECK(amount_paisa>=0));
CREATE TABLE return_allocations(id uuid PRIMARY KEY, return_line_id uuid NOT NULL REFERENCES return_lines, allocation_id uuid NOT NULL REFERENCES allocations, quarantine_batch_id uuid NOT NULL REFERENCES batches, quantity_base integer NOT NULL CHECK(quantity_base>0), cost_paisa bigint NOT NULL CHECK(cost_paisa>=0));
CREATE TABLE customer_entries(id uuid PRIMARY KEY, branch_id uuid NOT NULL REFERENCES branches, customer_id uuid NOT NULL REFERENCES customers, sale_id uuid NOT NULL REFERENCES sales, type text NOT NULL CHECK(type IN ('CREDIT_SALE','COLLECTION','RETURN_CREDIT')), amount_paisa bigint NOT NULL, method text CHECK(method IN ('CASH','CARD','WALLET')), shift_id uuid REFERENCES shifts, idempotency_key uuid NOT NULL, request_hash text NOT NULL, reference text NOT NULL DEFAULT '', actor_id uuid NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(branch_id,idempotency_key));
CREATE TABLE supplier_payments(id uuid PRIMARY KEY, branch_id uuid NOT NULL REFERENCES branches, supplier_id uuid NOT NULL REFERENCES suppliers, purchase_id uuid NOT NULL REFERENCES purchases, amount_paisa bigint NOT NULL CHECK(amount_paisa>0), method text NOT NULL CHECK(method IN ('CASH','CARD','WALLET')), shift_id uuid REFERENCES shifts, idempotency_key uuid NOT NULL, request_hash text NOT NULL, reference text NOT NULL, actor_id uuid NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(branch_id,idempotency_key));
CREATE TABLE expenses(id uuid PRIMARY KEY, branch_id uuid NOT NULL REFERENCES branches, shift_id uuid REFERENCES shifts, category text NOT NULL, amount_paisa bigint NOT NULL CHECK(amount_paisa>0), method text NOT NULL CHECK(method IN ('CASH','CARD','WALLET')), reference text NOT NULL, reason text NOT NULL, actor_id uuid NOT NULL REFERENCES users, idempotency_key uuid NOT NULL, request_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(branch_id,idempotency_key));
ALTER TABLE movements DROP CONSTRAINT movements_type_check;
ALTER TABLE movements ADD CONSTRAINT movements_type_check CHECK(type IN ('RECEIPT','SALE','RETURN_QUARANTINE','COUNT_ADJUSTMENT','WRITE_OFF'));
CREATE TABLE stock_counts(id uuid PRIMARY KEY, branch_id uuid NOT NULL REFERENCES branches, batch_id uuid NOT NULL REFERENCES batches, snapshot_quantity integer NOT NULL, counted_quantity integer NOT NULL CHECK(counted_quantity>=0), reason text NOT NULL, actor_id uuid NOT NULL REFERENCES users, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE count_approvals(id uuid PRIMARY KEY, count_id uuid NOT NULL UNIQUE REFERENCES stock_counts, approver_id uuid NOT NULL REFERENCES users, variance integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE backup_settings(id integer PRIMARY KEY CHECK(id=1), enabled boolean NOT NULL DEFAULT true, interval_hours integer NOT NULL DEFAULT 24 CHECK(interval_hours BETWEEN 1 AND 168));
INSERT INTO backup_settings(id) VALUES(1);
CREATE TABLE backup_runs(id uuid PRIMARY KEY, status text NOT NULL CHECK(status IN ('RUNNING','SUCCEEDED','FAILED')), filename text, sha256 text, schema_version text, app_version text NOT NULL, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, error text, restored_database text, verified_at timestamptz);
CREATE INDEX returns_sale ON returns(branch_id,sale_id);
CREATE INDEX customer_entries_account ON customer_entries(branch_id,customer_id,created_at);
CREATE INDEX supplier_payments_account ON supplier_payments(branch_id,supplier_id,created_at);
CREATE INDEX audit_branch_time ON audit_events(branch_id,created_at);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['shifts','shift_closings','returns','return_lines','return_allocations','customer_entries','supplier_payments','expenses','stock_counts','count_approvals'] LOOP EXECUTE format('CREATE TRIGGER immutable_history BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION deny_history_change()',t); END LOOP; END $$;
